9	function subscribeTheme(onChange: () => void) {
10	  const observer = new MutationObserver(onChange);
11	  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
12	  return () => observer.disconnect();
13	}
