15	/** Resolves a color token to a concrete color; tokens are light-dark() pairs, which ECharts cannot parse. */
16	function token(name: string, fallback: string) {
17	  if (typeof document === "undefined") return fallback;
18	  const probe = document.createElement("span");
19	  probe.style.color = `var(${name})`;
20	  document.body.appendChild(probe);
21	  const color = getComputedStyle(probe).color;
22	  probe.remove();
23	  return color || fallback;
24	}
