9	const day = (year: number, monthIndex: number, date: number) => new Date(Date.UTC(year, monthIndex, date)).toISOString().slice(0, 10);
10	const min = (a: string, b: string) => a < b ? a : b;
11	const MONTHS = 6;
12	const ROW_LIMIT = 50_000;
13	
14	// Totals come from reportExpenditure (exact-date FX, refunds subtracted, pending,
15	// transfers and review rows excluded). `partial` marks a total missing some rows.
16	function total(rows: SpendingRow[], rates: ExpenditureRate[], currencyCode: string, from: string, to: string): Total {
17	  const report = reportExpenditure(rows.map(expenditurePosting), rates, { view: "base", currencyCode, from, to });
18	  return { incomeMinor: BigInt(report.availableTotals.incomeMinor), spendingMinor: BigInt(report.availableTotals.spendingMinor), partial: report.status === "incomplete" };
19	}
