21	export function summarizeSpending(rows: SpendingRow[], rates: ExpenditureRate[], currencyCode: string, today: string) {
22	  const [year, month, date] = today.split("-").map(Number);
23	  const trend = Array.from({ length: MONTHS }, (_, index) => {
24	    const offset = MONTHS - 1 - index;
25	    const from = day(year, month - 1 - offset, 1), to = min(day(year, month - offset, 0), today);
26	    return { month: from.slice(0, 7), from, to, ...total(rows, rates, currencyCode, from, to) };
27	  });
28	  const thisMonth = trend[MONTHS - 1];
29	  // Same number of days into last month, clamped to its end (31 Mar compares with 28/29 Feb).
30	  const lastFrom = day(year, month - 2, 1), lastTo = min(day(year, month - 2, date), day(year, month - 1, 0));
31	  const lastMonthToDate = { from: lastFrom, to: lastTo, ...total(rows, rates, currencyCode, lastFrom, lastTo) };
32	  const top = (key: "category_id" | "merchant_id", from: string, to: string, metric: "spendingMinor" | "incomeMinor" = "spendingMinor") => {
33	    const current = rows.filter(row => row.posted_on >= from && row.posted_on <= to);
34	    const groups = new Map<string | null, SpendingRow[]>();
35	    for (const row of current) {
36	      const group = groups.get(row[key]);
37	      if (group) group.push(row); else groups.set(row[key], [row]);
38	    }
39	    return [...groups].map(([id, subset]) => ({ id, ...total(subset, rates, currencyCode, from, to) }))
40	      .filter(group => group[metric] > 0n)
41	      .sort((a, b) => a[metric] === b[metric] ? 0 : a[metric] < b[metric] ? 1 : -1)
42	      .slice(0, 5);
43	  };
44	  // Top lists for every trend month, so Home can switch months without another read.
45	  const months = trend.map(({ month, from, to }) => ({ month, from, to, categories: top("category_id", from, to), merchants: top("merchant_id", from, to),
46	    incomeCategories: top("category_id", from, to, "incomeMinor"), incomeMerchants: top("merchant_id", from, to, "incomeMinor") }));
47	  const { categories, merchants } = months[MONTHS - 1];
48	  return { currencyCode, trend, thisMonth, lastMonthToDate, months, categories, merchants };
49	}
