51	// One read of the last six months feeds the KPI tile, trend chart and top lists; memoized per request.
52	export const loadHomeSpending = cache(async (db: SupabaseClient, workspaceId: string, currencyCode: string, today: string) => {
53	  const [year, month] = today.split("-").map(Number);
54	  const from = day(year, month - MONTHS, 1);
55	  async function loadRows() {
56	    const rows: SpendingRow[] = [];
57	    for (let offset = 0; ; offset += 1000) {
58	      const { data, error } = await db.from("effective_transactions")
59	        .select("id, parent_transaction_id, account_id, posted_on, version, amount_minor::text, currency_code, status, kind, review_reasons, category_id, merchant_id")
60	        .eq("workspace_id", workspaceId).gte("posted_on", from).lte("posted_on", today).order("id").range(offset, offset + 999);
61	      if (error) throw error;
62	      rows.push(...(data ?? []) as unknown as SpendingRow[]);
63	      if (rows.length > ROW_LIMIT) throw new Error("Spending history exceeds the Home summary limit");
64	      if (!data || data.length < 1000) return rows;
65	    }
66	  }
67	  const [rows, rates] = await Promise.all([loadRows(), loadExpenditureRates(db, workspaceId, { currencyCode, from, to: today })]);
68	  const summary = summarizeSpending(rows, rates, currencyCode, today);
69	  async function names(table: "categories" | "merchants", groups: { id: string | null }[]) {
70	    const ids = groups.flatMap(group => group.id ? [group.id] : []);
71	    if (!ids.length) return new Map<string, string>();
72	    const { data, error } = await db.from(table).select("id, name").eq("workspace_id", workspaceId).in("id", ids);
73	    if (error) throw error;
74	    return new Map((data ?? []).map(row => [row.id as string, row.name as string]));
75	  }
76	  const [categoryNames, merchantNames] = await Promise.all([names("categories", summary.months.flatMap(m => [...m.categories, ...m.incomeCategories])), names("merchants", summary.months.flatMap(m => [...m.merchants, ...m.incomeMerchants]))]);
77	  return { ...summary, categoryNames, merchantNames };
78	});
